<script setup>
import { computed, reactive, ref } from 'vue';
import MButton from '../../../components/mds/MButton.vue'; import MCheckbox from '../../../components/mds/MCheckbox.vue'; import MInput from '../../../components/mds/MInput.vue'; import MRadioGroup from '../../../components/mds/MRadioGroup.vue'; import MSelect from '../../../components/mds/MSelect.vue'; import MTextarea from '../../../components/mds/MTextarea.vue'; import MUpload from '../../../components/mds/MUpload.vue';
const props = defineProps({ proposal: { type: Object, default: null }, processing: Boolean, saving: Boolean, error: { type: String, default: '' } }); const emit = defineEmits(['cancel', 'propose', 'confirm']);
const edits = reactive({ date: '', channel: '', result: '', summary: '', selected_person_id: '', selected_org_id: '', score_delta: 0 }); const localError = ref(''); const consent = ref(false); const hasProposal = computed(() => !!props.proposal); const candidateCount = computed(() => (props.proposal?.personCandidates?.length || 0) + (props.proposal?.orgCandidates?.length || 0));
const channelOptions = ['Gặp mặt', 'Điện thoại', 'Email', 'Sự kiện', 'Khác'].map((value) => ({ value, label: value })); const resultOptions = ['Tích cực', 'Trung lập', 'Cần theo dõi'].map((value) => ({ value, label: value }));
function select(files) { const file = files[0]; if (file) emit('propose', { audio: file, consent: consent.value }); } function selectPerson(value) { edits.selected_person_id = value; if (value) edits.selected_org_id = ''; } function selectOrg(value) { edits.selected_org_id = value; if (value) edits.selected_person_id = ''; } function syncProposal() { const v = props.proposal; if (!v) return; const total = v.personCandidates.length + v.orgCandidates.length; Object.assign(edits, { date: v.extracted.date || '', channel: v.extracted.channel || 'Gặp mặt', result: v.extracted.result || 'Tích cực', summary: v.extracted.summary || '', selected_person_id: total === 1 && v.personCandidates.length === 1 ? String(v.personCandidates[0].id) : '', selected_org_id: total === 1 && v.orgCandidates.length === 1 ? String(v.orgCandidates[0].id) : '', score_delta: v.suggestedScoreDelta || 0 }); } function confirm() { if (!props.proposal) return; localError.value = ''; const selected = Number(Boolean(edits.selected_person_id)) + Number(Boolean(edits.selected_org_id)); if (candidateCount.value > 1 && selected !== 1) { localError.value = 'Có nhiều kết quả phù hợp. Hãy chọn đúng một người liên hệ hoặc cơ quan trước khi xác nhận.'; return; } emit('confirm', { ...edits, selected_person_id: edits.selected_person_id || undefined, selected_org_id: edits.selected_org_id || undefined }); }
defineExpose({ syncProposal });
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><div class="mx-auto max-w-[880px] rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]"><header class="flex items-start justify-between gap-4 border-b border-[var(--mds-border-light)] px-5 py-4"><div><h1 class="text-[20px] font-semibold">Ghi tương tác bằng giọng nói</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">AI chỉ chuẩn bị đề xuất. Bạn phải rà soát và xác nhận trước khi lưu.</p></div><MButton variant="neutral" :disabled="processing || saving" @click="emit('cancel')">Hủy</MButton></header><div class="space-y-4 p-5"><template v-if="!hasProposal"><MCheckbox v-model="consent">Tôi đã được phép gửi bản ghi âm tới dịch vụ AI để gỡ băng và tạo bản nháp.</MCheckbox><p class="text-[12px] text-[var(--mds-text-secondary)]">Âm thanh chỉ được xử lý để tạo đề xuất; hệ thống không tự lưu tương tác hay thay đổi điểm quan hệ.</p><MUpload accept="audio/webm,audio/wav,audio/mpeg,audio/mp4,audio/ogg,audio/aiff" :multiple="false" :max-size-m-b="25" label="Tệp ghi âm" :disabled="processing || !consent" @select-files="select" /><p class="text-[12px] text-[var(--mds-text-secondary)]">Thu âm trực tiếp trong AMIS Mobile chưa sẵn sàng; hãy chọn tệp audio hợp lệ.</p></template><template v-else><p class="rounded-lg bg-[var(--mds-brand-50)] px-3 py-2 text-[13px] text-[var(--mds-brand-700)]">Đề xuất hết hạn: {{ proposal.expiresAt }}. Không có dữ liệu nào được lưu cho đến khi bạn xác nhận.</p><label><span class="mb-1 block text-[13px] font-medium">Ngày</span><MInput v-model="edits.date" type="date" /></label><div class="grid gap-4 sm:grid-cols-2"><label><span class="mb-1 block text-[13px] font-medium">Kênh</span><MSelect v-model="edits.channel" :options="channelOptions" /></label><label><span class="mb-1 block text-[13px] font-medium">Kết quả</span><MSelect v-model="edits.result" :options="resultOptions" /></label></div><label><span class="mb-1 block text-[13px] font-medium">Nội dung</span><MTextarea v-model="edits.summary" /></label><p v-if="candidateCount > 1" class="rounded-lg bg-[var(--mds-bg-warning-warning-light)] px-3 py-2 text-[13px] text-[var(--mds-text-warning)]">AI tìm thấy nhiều kết quả. Hãy chọn đúng một kết quả trước khi xác nhận.</p><section v-if="proposal.personCandidates.length"><span class="mb-2 block text-[13px] font-medium">Người liên hệ</span><MRadioGroup :model-value="edits.selected_person_id" direction="vertical" :options="proposal.personCandidates.map((item) => ({ value: String(item.id), label: `${item.name}${item.org_name ? ' · ' + item.org_name : ''}` }))" @update:model-value="selectPerson" /></section><section v-if="proposal.orgCandidates.length"><span class="mb-2 block text-[13px] font-medium">Cơ quan</span><MRadioGroup :model-value="edits.selected_org_id" direction="vertical" :options="proposal.orgCandidates.map((item) => ({ value: String(item.id), label: `${item.name}${item.org_type ? ' · ' + item.org_type : ''}` }))" @update:model-value="selectOrg" /></section><label v-if="edits.selected_person_id"><span class="mb-1 block text-[13px] font-medium">Điều chỉnh điểm quan hệ</span><MInput v-model="edits.score_delta" type="number" min="-10" max="10" /><span class="mt-1 block text-[12px] text-[var(--mds-text-secondary)]">Đề xuất từ AI có thể sửa trong khoảng -10 đến 10; máy chủ sẽ kiểm tra lại quyền sửa người liên hệ.</span></label></template><p v-if="error || localError" role="alert" class="rounded-lg bg-[var(--mds-bg-danger-danger-light)] px-3 py-2 text-[13px] text-[var(--mds-text-danger)]">{{ error || localError }}</p></div><footer class="sticky bottom-0 flex justify-end gap-2 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-5 py-3"><MButton variant="neutral" :disabled="processing || saving" @click="emit('cancel')">Hủy</MButton><MButton v-if="hasProposal" variant="primary" :loading="saving" @click="confirm">Xác nhận ghi tương tác</MButton></footer></div></section></template>
